-- Durable invalidation is in the same Core transaction as its metadata change.
-- @d1-verify {"type":"table","name":"search_metadata_repairs_v1","sqlIncludes":["revision integer","fencing_token integer"]}
CREATE TABLE IF NOT EXISTS search_metadata_repairs_v1 (article_id TEXT PRIMARY KEY NOT NULL, revision INTEGER NOT NULL CHECK(revision>0), applied_revision INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL CHECK(status IN ('pending','leased','retry_wait','verified','dead_letter')), fencing_token INTEGER NOT NULL DEFAULT 0, lease_until TEXT, attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT, first_failure_at TEXT, last_error_code TEXT, updated_at TEXT NOT NULL, verified_at TEXT);
CREATE INDEX IF NOT EXISTS search_metadata_due ON search_metadata_repairs_v1(status,next_attempt_at,lease_until);
CREATE TABLE IF NOT EXISTS search_metadata_policy_v1 (id INTEGER PRIMARY KEY CHECK(id=1), public_read_required INTEGER NOT NULL DEFAULT 0 CHECK(public_read_required IN(0,1)));
INSERT OR IGNORE INTO search_metadata_policy_v1 VALUES(1,0);
CREATE TRIGGER IF NOT EXISTS metadata_article_tags_insert AFTER INSERT ON article_tags WHEN EXISTS(SELECT 1 FROM article_publications_p3 WHERE article_id=NEW.article_id AND state='published') BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (NEW.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_article_tags_update AFTER UPDATE ON article_tags WHEN EXISTS(SELECT 1 FROM article_publications_p3 WHERE article_id=NEW.article_id AND state='published') BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (NEW.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_article_tags_move AFTER UPDATE ON article_tags WHEN OLD.article_id<>NEW.article_id AND EXISTS(SELECT 1 FROM article_publications_p3 WHERE article_id=OLD.article_id AND state='published') BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (OLD.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_article_tags_delete AFTER DELETE ON article_tags WHEN EXISTS(SELECT 1 FROM article_publications_p3 WHERE article_id=OLD.article_id AND state='published') BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (OLD.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
