CREATE TRIGGER IF NOT EXISTS metadata_article_publications_p3_delete AFTER DELETE ON article_publications_p3 BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (OLD.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_legacy_version_freshness_classifications_v4_insert AFTER INSERT ON legacy_version_freshness_classifications_v4 WHEN EXISTS(SELECT 1 FROM article_content_versions_p3 WHERE id=NEW.version_id) BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES ((SELECT article_id FROM article_content_versions_p3 WHERE id=NEW.version_id),1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_legacy_version_freshness_classifications_v4_update AFTER UPDATE ON legacy_version_freshness_classifications_v4 WHEN EXISTS(SELECT 1 FROM article_content_versions_p3 WHERE id=NEW.version_id) BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES ((SELECT article_id FROM article_content_versions_p3 WHERE id=NEW.version_id),1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
