CREATE TRIGGER IF NOT EXISTS metadata_case_catalog_publications_v1_insert AFTER INSERT ON case_catalog_publications_v1 BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (NEW.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_case_catalog_publications_v1_update AFTER UPDATE ON case_catalog_publications_v1 BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (NEW.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_case_catalog_publications_v1_delete AFTER DELETE ON case_catalog_publications_v1 BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (OLD.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_review_update AFTER UPDATE OF review_state ON articles WHEN NEW.review_state IS NOT OLD.review_state AND EXISTS(SELECT 1 FROM article_publications_p3 WHERE article_id=NEW.id AND state='published') BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) VALUES (NEW.id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now')) ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TRIGGER IF NOT EXISTS metadata_tag_update AFTER UPDATE OF slug,name,normalized_name,type ON tags WHEN NEW.slug IS NOT OLD.slug OR NEW.name IS NOT OLD.name OR NEW.normalized_name IS NOT OLD.normalized_name OR NEW.type IS NOT OLD.type BEGIN INSERT INTO search_metadata_repairs_v1(article_id,revision,status,updated_at) SELECT DISTINCT at.article_id,1,'pending',strftime('%Y-%m-%dT%H:%M:%fZ','now') FROM article_tags at JOIN article_publications_p3 p ON p.article_id=at.article_id AND p.state='published' WHERE at.tag_id=NEW.id AND 1 ON CONFLICT(article_id) DO UPDATE SET revision=revision+1,status='pending',fencing_token=fencing_token+1,lease_until=NULL,attempt_count=0,next_attempt_at=NULL,updated_at=excluded.updated_at; END;
CREATE TABLE IF NOT EXISTS search_metadata_attempts_v1(article_id TEXT NOT NULL,revision INTEGER NOT NULL,fencing_token INTEGER NOT NULL,status TEXT NOT NULL,error_code TEXT,started_at TEXT NOT NULL,finished_at TEXT,PRIMARY KEY(article_id,revision,fencing_token));
